//! Replays the picoclaw fixtures against this crate.
//!
//! Run with `cargo test --test conformance`. The corpus is generated by Go code,
//! so a failure means one of two things: the Rust port drifted, or the Go
//! behaviour changed on purpose and the fixtures are stale. `conformance/README.md`
//! says how to tell which, and which one to fix.

use conformance::{go_value::to_go_value, Fixture, Report};
use crab_tokenizer::{
    ContentBlock, FunctionCall, Message, ToolCall, ToolDefinition, ToolFunctionDefinition,
};
use serde_json::{json, Value};

#[test]
fn estimate_message_tokens_matches_go() {
    let fixture = Fixture::load("tokenizer_estimate_message_tokens.json");
    let mut report = Report::new(&fixture);

    for case in &fixture.cases {
        let input: FixtureMessage = case.parse();
        let got = crab_tokenizer::estimate_message_tokens(&input.into_message());
        report.record(case, json!(got));
    }

    report.finish(12);
}

#[test]
fn estimate_tool_defs_tokens_matches_go() {
    let fixture = Fixture::load("tokenizer_estimate_tool_defs_tokens.json");
    let mut report = Report::new(&fixture);

    for case in &fixture.cases {
        let input: FixtureToolDefs = case.parse();
        let got = crab_tokenizer::estimate_tool_defs_tokens(&input.into_defs());
        report.record(case, json!(got));
    }

    report.finish(12);
}

// ------------------------------------------------------------- message input --

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct FixtureMessage {
    content: String,
    reasoning_content: String,
    system_parts: Vec<FixturePart>,
    tool_calls: Vec<FixtureToolCall>,
    tool_call_id: String,
    /// The estimator only counts media items, so the fixture records a count
    /// instead of inventing paths that would imply the contents matter.
    media_count: usize,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct FixturePart {
    #[serde(rename = "type")]
    part_type: String,
    text: String,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct FixtureToolCall {
    id: String,
    #[serde(rename = "type")]
    call_type: String,
    name: String,
    function: Option<FixtureFunctionCall>,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct FixtureFunctionCall {
    name: String,
    arguments: String,
}

impl FixtureMessage {
    fn into_message(self) -> Message {
        Message {
            role: "user".into(),
            content: self.content,
            reasoning_content: self.reasoning_content,
            system_parts: self
                .system_parts
                .into_iter()
                .map(|p| ContentBlock {
                    part_type: p.part_type,
                    text: p.text,
                })
                .collect(),
            tool_calls: self
                .tool_calls
                .into_iter()
                .map(|tc| ToolCall {
                    id: tc.id,
                    call_type: tc.call_type,
                    function: tc.function.map(|f| FunctionCall {
                        name: f.name,
                        arguments: f.arguments,
                    }),
                    name: tc.name,
                })
                .collect(),
            tool_call_id: self.tool_call_id,
            media: (0..self.media_count)
                .map(|i| format!("media-{i}"))
                .collect(),
        }
    }
}

// ---------------------------------------------------------- tool defs input --

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct FixtureToolDefs {
    defs: Vec<FixtureToolDef>,
}

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct FixtureToolDef {
    name: String,
    description: String,
    parameters: Option<Value>,
}

impl FixtureToolDefs {
    fn into_defs(self) -> Vec<ToolDefinition> {
        self.defs
            .into_iter()
            .map(|d| ToolDefinition {
                def_type: "function".into(),
                function: ToolFunctionDefinition {
                    name: d.name,
                    description: d.description,
                    parameters: d.parameters.map(|p| to_go_value(&p)),
                },
            })
            .collect()
    }
}
